SELECT clock_timestamp() AS db_at,o.external_order_id,k.id,k.product_id,k.source_storage_location_id,k.sorting_storage_location_id,k.picked_at,k.undone_at FROM fbs_orders o JOIN fbs_order_products p ON p.order_id=o.id JOIN fbs_order_product_picks k ON k.order_product_id=p.id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon' ORDER BY o.external_order_id,k.id LIMIT 100
